        if not isinstance(m,list): continue
        for c in m:
            if c.get('type')=='tool_use' and c.get('name')=='AskUserQuestion':
                s=json.dumps(c['input'])
                if 'server' in s and ('Sentry' in s):
                    print('ASK',f[:8],ts); print(s[:5000]); print('---')
