import json,glob,re
f=[x for x in glob.glob('591dc086*.jsonl')][0]
rows=[json.loads(l) for l in open(f) if l.strip().startswith('{')]
def text(d):
    m=d.get('message',{}).get('content')
    if isinstance(m,str): return m
    if isinstance(m,list): return '\n'.join(c.get('text','') for c in m if c.get('type')=='text')
    return ''
idx=[i for i,d in enumerate(rows) if str(d.get('timestamp','')).startswith('2026-11-15T05:11:58')]
i=idx[0]
# previous user text messages (3) and following (4)
def is_user_text(d):
    return d.get('type')=='user' and text(d).strip() and not text(d).startswith('<')
prev=[j for j in range(i) if is_user_text(rows[j])][-3:]
nxt=[j for j in range(i+1,len(rows)) if is_user_text(rows[j])][:6]
for j in prev: print('USER',rows[j].get('timestamp'),':',text(rows[j])[:1500]); print('--')
print('ASSISTANT',rows[i].get('timestamp'),':',text(rows[i])[:3500]); print('--')
for j in nxt: print('USER',rows[j].get('timestamp'),':',text(rows[j])[:1200]); print('--')
# any later assistant/user mention of route
for d in rows[i+1:]:
    t=text(d)
    if re.search(r'(straight to Sentry|directly to Sentry|to our own server|through our own server|own server, which)',t) and len(t)<6000:
        for p in t.split('\n'):
            if re.search(r'(straight to Sentry|directly to Sentry|own server)',p): print(d.get('type').upper(),d.get('timestamp'),':',p[:700]); print('..')
EOF

