#pragma once

// How one error report (ErrorReport.hpp) reaches Sentry: the address and key
// a Sentry DSN names, and the envelope, Sentry's upload format, that carries
// the report as one event. No wx and no network, so the tests can read what
// would be sent.

#include "ErrorReport.hpp"

#include <optional>
#include <string>
#include <vector>

namespace Slic3r::GUI::JusPrin {

// A DSN, "https://<public key>@<host>/<project>", as an upload address and key.
// The key can only send new events, so it may ship inside the app.
struct SentryDsn
{
    std::string envelope_url; // "https://<host>/api/<project>/envelope/"
    std::string public_key;
};

// nullopt for an empty DSN or one not in that shape.
std::optional<SentryDsn> parse_sentry_dsn(const std::string& dsn);

// The X-Sentry-Auth header value for `client`, as "jusprin.app/2.0.0".
std::string sentry_auth_header(const SentryDsn& dsn, const std::string& client);

// What Sentry groups by: what the app was doing and the error, without the ids
// that differ every time one failure happens (the app's own "(request <turn>
// #<n>, its request id <id>)" and a provider body's "request_id"), so two
// reports of one failure are one Sentry issue. The ids stay in the message.
std::vector<std::string> sentry_fingerprint(const ErrorReport& report);

// The envelope that uploads `report` as one event. `event_id` is 32 hex
// digits, `timestamp` seconds since 1970, `version` the app's own version.
// It holds the report's lines and what Sentry needs to file them: the release
// (the app line), the tags (what the app was doing, the system), the grouping
// above, and the platform "native", which, unlike "javascript", never makes
// Sentry fill in the sender's network address; nor does the SDK setting
// infer_ip "never". There is no user.
std::string sentry_envelope(const ErrorReport& report, const std::string& event_id, double timestamp, const std::string& version);

