    19	std::string tag_value(std::string text)
    20	{
    21	    constexpr std::size_t limit = 200;
    22	    if (text.size() > limit) {
    23	        std::size_t end = limit;
    24	        while (end > 0 && (static_cast<unsigned char>(text[end]) & 0xC0) == 0x80)
