    33	std::optional<SentryDsn> parse_sentry_dsn(const std::string& dsn)
    34	{
    35	    // <scheme>://<key>[:<secret>]@<host>[:<port>][/<path>]/<project>
    36	    static const std::regex shape(R"(^(https?)://([^:@/]+)(?::[^@/]*)?@([^/]+)(/(?:[^/]+/)*)([0-9]+)/?$)");
    37	    std::smatch part;
    38	    if (!std::regex_match(dsn, part, shape))
    39	        return std::nullopt;
    40	    return SentryDsn{part[1].str() + "://" + part[3].str() + part[4].str() + "api/" + part[5].str() + "/envelope/", part[2].str()};
    41	}
    42	
    43	std::string sentry_auth_header(const SentryDsn& dsn, const std::string& client)
    44	{
    45	    return "Sentry sentry_version=7, sentry_client=" + client + ", sentry_key=" + dsn.public_key;
